+static void serial_ambarella_console_device_lock(struct console *co,
+						 unsigned long *flags)
+{
+	__uart_port_lock_irqsave(&ambarella_port[co->index].port, flags);
+}
+
+static void serial_ambarella_console_device_unlock(struct console *co,
+						   unsigned long flags)
+{
