+		seq_printf(s, " gpio-%-3d", gc->base + i);
+
+		alt = ((iomux2 >> i) & 1) << 2;
+		alt |= ((iomux1 >> i) & 1) << 1;
+		alt |= ((iomux0 >> i) & 1) << 0;
+		if (alt) {
+			seq_printf(s, " [HW  ] (alt%d)\n", alt);
+		} else {
+			char *label __free(kfree) = gpiochip_dup_line_label(gc, i);
+			if (IS_ERR(label)) {
+				pr_debug("Failed to duplicate label\n");
+				continue;
+			}
+
+			seq_printf(s, " [GPIO] (%-20.20s) %s %s\n",
+				   label ? label : "",
+				   (dir & BIT(i)) ? "out" : "in ",
+				   (data & BIT(i)) ? "hi" : "lo");
+		}
+	}
+}
